import sys

def process_suffixes(s):
    n = len(s)
    results = []
    for i in range(n):
        result = []
        j = i
        while j < n:
            result.append(s[j])
            while j + 1 < n and s[j] == s[j + 1]:
                j += 1
            j += 1
        result_str = ''.join(result)
        if len(result_str) > 10:
            result_str = result_str[:5] + '...' + result_str[-2:]
        results.append(result_str)
    return results

def main():
    import sys
    s = sys.stdin.read().strip()
    results = process_suffixes(s)
    for result in results:
        print(f"{len(result)} {result}")

if __name__ == "__main__":
    main()
